DTM_CROPS = HERE / "data" / "dtm_crops"
MARS_RADIUS_M = 3_396_190.0  # same sphere used in cases.py
MAP_HALF_SPAN_M = 250.0
POINT_SPACING_M = 50.0
MIN_DISTANCE_M = 50.0
MAX_DISTANCE_M = 500.0

ACTUAL = "NASA recorded path"
FASTEST = "Fastest path"
LOWEST = "Lowest-energy path"
ROUTE_NAMES = (ACTUAL, FASTEST, LOWEST)
ROUTE_STYLES = {
    ACTUAL: ("#ea580c", ()),
    FASTEST: ("#0284c7", (8, 4)),
    LOWEST: ("#8b5cf6", (5, 4)),
}

XY = tuple[float, float]


@dataclass(frozen=True)
class RoverPoint:
    """Point at a sampled distance along a *recorded* NASA route."""

    name: str
    x_m: float
    y_m: float
    along_m: float = 0.0
    lon: float | None = None
    lat: float | None = None


@dataclass(frozen=True)
class RouteDisplay:
    name: str
    coordinates: tuple[XY, ...]
    distance_m: float | None
    time_s: float | None
    energy_j: float | None
    note: str
    ascent_m: float | None = None
    descent_m: float | None = None

    @property
    def energy_wh(self) -> float | None:
        return None if self.energy_j is None else self.energy_j / 3600.0


def local_xy(lonlat: Sequence[Sequence[float]], ref_lon: float, ref_lat: float) -> list[XY]:
    """Local Mars tangent-plane meters for PREVIEW only (no terrain loaded).

    Once terrain is loaded, the precise projected Terrain._to_xy is used.
    The 500 m display uses a single metric x/y frame for all overlays.
    """
    cos_lat = math.cos(math.radians(ref_lat))
    return [
        (MARS_RADIUS_M * math.radians(float(lon) - ref_lon) * cos_lat,
         MARS_RADIUS_M * math.radians(float(lat) - ref_lat))
        for lon, lat in lonlat
    ]


def cumulative_distances(coords: Sequence[XY]) -> list[float]:
    if not coords:
        return []
    cum = [0.0]
    for a, b in zip(coords, coords[1:]):
        cum.append(cum[-1] + math.hypot(b[0] - a[0], b[1] - a[1]))
    return cum


def interpolate_at(coords: Sequence[XY], cumulative: Sequence[float], pos: float) -> XY:
    if not coords:
        raise ValueError("Recorded path must not be empty")
    if pos <= 0:
        return coords[0]
    if pos >= cumulative[-1]:
        return coords[-1]
    import bisect
    i = min(max(bisect.bisect_right(cumulative, pos) - 1, 0), len(coords) - 2)
    while i + 1 < len(cumulative) - 1 and cumulative[i + 1] <= cumulative[i]:
        i += 1
    span = cumulative[i + 1] - cumulative[i]
    t = (pos - cumulative[i]) / span if span else 0.0
    a, b = coords[i], coords[i + 1]
    return (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1]))


def sample_recorded_track(
    coords: Sequence[XY], spacing_m: float = POINT_SPACING_M,
) -> list[RoverPoint]:
    """Resample points *on* an observed polyline, without inventing a route.

    Always include end. If the last interval is <40% spacing, merge it into
    the previous interval rather than adding almost-overlapping markers.
    """
    if len(coords) < 2 or spacing_m <= 0:
        raise ValueError("Need a recorded line with >=2 points and spacing > 0")
    cum = cumulative_distances(coords)
    length = cum[-1]
    if length <= 0:
        raise ValueError("Recorded track has zero measured length")
    # Evenly distribute the markers so the first and last are real endpoints;
    # each intermediate one is approximately spacing_m along the NASA line.
    # This avoids a tiny final interval (e.g. 4 m after a 400 m marker).
    intervals = max(1, int(math.floor(length / spacing_m + 0.5)))
    targets = [length * k / intervals for k in range(intervals + 1)]
    return [
        RoverPoint(f"P{i:02d}", *interpolate_at(coords, cum, s), along_m=s)
        for i, s in enumerate(targets, start=1)
    ]


def recorded_subpath(coords: Sequence[XY], start_m: float, end_m: float) -> list[XY]:
    """Precise sub-polyline between two arclength positions, in requested order."""
    if not coords:
        return []
    cum = cumulative_distances(coords)
    reverse = start_m > end_m
    lo, hi = (end_m, start_m) if reverse else (start_m, end_m)
    if lo < -1e-6 or hi > cum[-1] + 1e-6:
        raise ValueError("Selection is outside NASA recorded track")
    middle = [coords[i] for i, s in enumerate(cum) if lo < s < hi]
    result = [interpolate_at(coords, cum, lo), *middle,
              interpolate_at(coords, cum, hi)]
    return list(reversed(result)) if reverse else result


def read_cases(path: Path = CASES_FILE) -> list[dict]:
    if not path.is_file():
        return []
    with path.open(encoding="utf-8") as file:
        data = json.load(file)
    if not isinstance(data, list):
        raise ValueError("data/cases.json should be a JSON list of case objects")
    return [case for case in data
            if isinstance(case, dict) and len(case.get("nasa_route_lonlat", [])) >= 2]


def find_local_dtm(case_id: str) -> Path | None:
    # Crop wins for quick loading; all choices stay local and offline.
    crop = DTM_CROPS / f"{case_id}.tif"
    if crop.is_file():
        return crop
    if DTM_FULL.is_file():
        return DTM_FULL
    return None


def map_center(track_xy: Sequence[XY]) -> XY:
    return ((min(p[0] for p in track_xy) + max(p[0] for p in track_xy)) / 2,
            (min(p[1] for p in track_xy) + max(p[1] for p in track_xy)) / 2)


def projected_track(terrain, lonlat: Sequence[Sequence[float]]) -> list[XY]:
    """Use terrain.py's true-scale local Mars projection, not Earth lat/lon."""
    projector = terrain._to_xy  # cached pyproj transformer created by Terrain
    return [tuple(map(float, projector.transform(float(p[0]), float(p[1]))))
            for p in lonlat]


def route_cells_near_recorded_line(terrain, xy_line: Sequence[XY]) -> list[tuple[int, int]]:
    """Snap a real polyline to a sequence of adjacent grid centers at <=0.5 m steps.

    This is ONLY for model-cost estimation; the displayed NASA path remains
    the unmodified recorded NASA polyline. The snapped route is not claimed
    to be a true driven 2 m cell-center path.
    """
    inv = ~terrain.transform
    rows, cols = terrain.elev.shape
    step_m = min(float(terrain.cell_size) * 0.24, 0.5)
    out: list[tuple[int, int]] = []
    for a, b in zip(xy_line, xy_line[1:]):
        n = max(1, int(math.ceil(math.hypot(b[0]-a[0], b[1]-a[1]) / step_m)))
        for i in range(n + 1):
            t = i / n
            xf, yf = a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1])
            cf, rf = inv * (xf, yf)
            cell = (math.floor(rf), math.floor(cf))
            if not (0 <= cell[0] < rows and 0 <= cell[1] < cols):
                raise ValueError("Recorded NASA path leaves the loaded terrain grid")
            if not out or out[-1] != cell:
                out.append(cell)
    return out


def evaluate_recorded_path(model, terrain, xy_line: Sequence[XY]) -> tuple[float | None, float | None, str]:
    """Model time and energy along NASA geometry; unavailable if blocked."""
    try:
        cells = route_cells_near_recorded_line(terrain, xy_line)
        result = model.evaluate_path(cells)
        if not result.passable:
            return None, None, "Model rejects at least one recorded-track tile/transition; estimates unavailable."
        return result.time_s, result.energy_j, "Modeled from NASA track snapped to 2 m cells (NOT measured)."
    except (ValueError, IndexError) as exc:
        return None, None, f"Model estimate unavailable: {exc}"


def cell_xy(terrain, cells: Sequence[tuple[int, int]]) -> tuple[XY, ...]:
    return tuple(tuple(map(float, terrain.transform * (c + 0.5, r + 0.5)))
                 for r, c in cells)


def nearest_passable(model, terrain, xy: XY, max_offset_m: float = 4.0) -> tuple[tuple[int, int], float]:
    """Explicitly snap a NASA marker to a nearby passable 2 m cell if required.

    Endpoints can be interpolated on a path and fall in a conservative blocked
    tile. Snap must be reported in the UI and is limited to 4 m, not silent.
    """
    col_f, row_f = (~terrain.transform) * xy
    base = (math.floor(row_f), math.floor(col_f))
    radius = int(math.ceil(max_offset_m / float(terrain.cell_size))) + 1
    options = []
    rows, cols = model.elev.shape
    for r in range(base[0] - radius, base[0] + radius + 1):
        for c in range(base[1] - radius, base[1] + radius + 1):
            if 0 <= r < rows and 0 <= c < cols:
                p = terrain.transform * (c + 0.5, r + 0.5)
                d = math.hypot(p[0] - xy[0], p[1] - xy[1])
                if d <= max_offset_m and model.evaluate_tile(r, c).passable:
                    options.append((d, (r, c)))
    if not options:
        raise ValueError(f"No passable tile within {max_offset_m:g} m of a selected rover point")
    options.sort()
    return options[0][1], options[0][0]


def calculate_real_routes(terrain, track_xy: Sequence[XY], start: RoverPoint,
                          end: RoverPoint) -> dict[str, RouteDisplay]:
    """Pure worker-side route calculation; also easy to unit-test headlessly."""
    from optimization import PathOptimizer
    from traversability import TraversabilityModel

    model = TraversabilityModel(terrain)
    actual = recorded_subpath(track_xy, start.along_m, end.along_m)
    recorded_length = cumulative_distances(actual)[-1]
    t, e, actual_note = evaluate_recorded_path(model, terrain, actual)
    if start.along_m > end.along_m:
        actual_note = "Reverse of NASA recorded chronology. " + actual_note
    result = {
        ACTUAL: RouteDisplay(ACTUAL, tuple(actual), recorded_length, t, e,
                             actual_note)
    }

    def not_found(name: str, reason: str) -> RouteDisplay:
        return RouteDisplay(name, (), None, None, None, reason)

    try:
        start_cell, start_snap = nearest_passable(model, terrain, (start.x_m, start.y_m))
        end_cell, end_snap = nearest_passable(model, terrain, (end.x_m, end.y_m))
    except ValueError as exc:
        result[FASTEST] = not_found(FASTEST, str(exc))
        result[LOWEST] = not_found(LOWEST, str(exc))
        return result

    optimized = PathOptimizer(model).optimize(start_cell, end_cell)
    snap_note = f"Grid endpoints offset {start_snap:.1f} m / {end_snap:.1f} m from NASA markers."
    for name, route in ((FASTEST, optimized.fastest),
                        (LOWEST, optimized.lowest_energy)):
        if route.found:
            result[name] = RouteDisplay(
                name, cell_xy(terrain, route.cells), route.distance_m,
                route.time_s, route.energy_j,
                "A* on 2 m tiles; no charging. " + snap_note,
                route.ascent_m, route.descent_m,
            )
        else:
            result[name] = not_found(name, route.reason)
    return result


def terrain_rgb(terrain, bounds: tuple[float, float, float, float], size: int) -> np.ndarray:
    """North-up color hillshade from *real elevation* inside requested bounds."""
    left, right, bottom, top = bounds
    inv = ~terrain.transform
    xs = left + (np.arange(size) + 0.5) * (right - left) / size
    ys = top - (np.arange(size) + 0.5) * (top - bottom) / size
    x_mesh, y_mesh = np.meshgrid(xs, ys)
    cols_f = inv.a * x_mesh + inv.b * y_mesh + inv.c
    rows_f = inv.d * x_mesh + inv.e * y_mesh + inv.f
    rr, cc = np.floor(rows_f).astype(int), np.floor(cols_f).astype(int)
    h, w = terrain.elev.shape
    inside = (rr >= 0) & (rr < h) & (cc >= 0) & (cc < w)
    elev = np.full((size, size), np.nan, dtype=float)
    elev[inside] = np.asarray(terrain.elev, dtype=float)[rr[inside], cc[inside]]
    valid = np.isfinite(elev)
    rgb = np.zeros((size, size, 3), dtype=np.uint8)
    rgb[:] = (54, 54, 60)
    if not np.any(valid):
        return rgb

    low, high = np.percentile(elev[valid], [3, 97])
    rng = max(float(high - low), 0.01)
    norm = np.clip((elev - low) / rng, 0, 1)
    # Warm, Mars-like elevation palette. This is a COLORIZATION of topography,
    # NOT a genuine visible-light satellite image.
    land = np.stack([161 + 76 * norm, 105 + 61 * norm, 76 + 40 * norm], axis=-1)
    filled = np.where(valid, elev, np.nanmedian(elev[valid]))
    meters_per_pixel = (right - left) / max(size, 1)
    dy, dx = np.gradient(filled, meters_per_pixel, meters_per_pixel)
    illum = np.clip(0.80 + 1.5 * (-0.7 * dx - 0.7 * dy), 0.46, 1.23)
    land *= illum[..., None]
    rgb[valid] = np.clip(land[valid], 0, 255).astype(np.uint8)
    return rgb


class MarsRoverUI(ttk.Frame):
    """Tkinter UI. Real data is loaded from cases.json; DTM loads in background.

    A supplied `cases_path` can point to another case file, and `dtm_path`
    overrides automatic local crop/full-DTM discovery. The parent Tk is owned
    by main.py via launch_ui().
    """

    def __init__(self, parent: tk.Misc, *, cases_path: str | Path = CASES_FILE,
                 dtm_path: str | Path | None = None) -> None:
        super().__init__(parent, padding=12)
        self.parent = parent
        self.cases = read_cases(Path(cases_path))
        self.case = None
        self.case_map: dict[str, dict] = {}
        self.selected_dtm = Path(dtm_path) if dtm_path else None
        self.terrain = None
        self.track_xy: list[XY] = []
        self.points: list[RoverPoint] = []
        self.by_name: dict[str, RoverPoint] = {}
        self.center_xy: XY = (0.0, 0.0)
        self.routes: dict[str, RouteDisplay] = {}
        self._canvas_image = None
        self._loaded_map_image = None
        self._custom_map_bounds = None
        self._cache_image_key = None
        self._map_geometry = (0, 0, 1)
        self._marker_pixels: dict[str, XY] = {}
        self._result_queue: queue.Queue = queue.Queue()
        self._generation = 0
        self.loading = False
        self.calculating = False
        self.dtm_error = ""
        self.selected_case = tk.StringVar()
        self.start_name = tk.StringVar()
        self.end_name = tk.StringVar()
        self.distance_text = tk.StringVar(value="Select two rover positions")
        self.status_text = tk.StringVar(value="Loading recorded case tracks...")
        self.data_text = tk.StringVar(value="")
        self.show_route = {name: tk.BooleanVar(value=True) for name in ROUTE_NAMES}
        self.metric_text = {name: tk.StringVar(value="Not calculated") for name in ROUTE_NAMES}
        self._build_ui()
        if self.cases:
            self.case_map = {c.get("id", f"case{i+1}"): c for i, c in enumerate(self.cases)}
            self.case_combo.configure(values=list(self.case_map))
            self.selected_case.set(next(iter(self.case_map)))
            self._change_case()
        else:
            self.case_combo.configure(state="disabled")
            self.calculate_button.configure(state="disabled")
            self.status_text.set("No recorded cases found. Run 'python cases.py' to create data/cases.json.")
            self.data_text.set("NASA case data unavailable; no fictional points are shown.")
        self.after(120, self._poll_worker_results)
        self.after_idle(self._redraw)

    def _build_ui(self) -> None:
        self.pack(fill="both", expand=True)
        self.columnconfigure(0, weight=1)
        self.rowconfigure(2, weight=1)
        ttk.Label(self, text="MARS ROVER  |  PATH COMPARISON",
                  font=("Segoe UI", 19, "bold")).grid(row=0, column=0, columnspan=2,
                                                        sticky="w", pady=(0, 4))
        ttk.Label(self, text="Recorded NASA route  •  2 m terrain costs  •  500 m × 500 m map",
                  foreground="#596474").grid(row=1, column=0, columnspan=2,
                                                sticky="w", pady=(0, 10))

        map_frame = ttk.Frame(self)
        map_frame.grid(row=2, column=0, sticky="nsew", padx=(0, 16))
        map_frame.columnconfigure(0, weight=1)
        map_frame.rowconfigure(0, weight=1)
        self.canvas = tk.Canvas(map_frame, bg="#272a31", width=790, height=670,
                                highlightthickness=0)
        self.canvas.grid(row=0, column=0, sticky="nsew")
        self.canvas.bind("<Configure>", lambda _: self._redraw())
        self.canvas.bind("<Button-1>", self._map_click)
        ttk.Label(map_frame,
                  text="North up  •  250 m each way from center  •  Mars local meters  •  markers interpolated ~50 m along NASA track",
                  wraplength=880, foreground="#596474").grid(row=1, column=0,
                                                                sticky="w", pady=(5, 0))

        # Sidebar scrolls on smaller laptop screens so route statistics do
        # not get clipped when all three reports have notes/warnings.
        sidebar_outer = ttk.Frame(self, width=355)
        sidebar_outer.grid(row=2, column=1, sticky="nsew")
        sidebar_outer.grid_propagate(False)
        sidebar_outer.columnconfigure(0, weight=1)
        sidebar_outer.rowconfigure(0, weight=1)
        sidebar_canvas = tk.Canvas(sidebar_outer, highlightthickness=0,
                                    width=335, bd=0)
        sidebar_canvas.grid(row=0, column=0, sticky="nsew")
        bar = ttk.Scrollbar(sidebar_outer, orient="vertical",
                            command=sidebar_canvas.yview)
        bar.grid(row=0, column=1, sticky="ns")
        sidebar_canvas.configure(yscrollcommand=bar.set)
        side = ttk.Frame(sidebar_canvas, padding=(0, 0, 5, 0))
        window_id = sidebar_canvas.create_window((0, 0), anchor="nw", window=side)
        side.bind("<Configure>", lambda _: sidebar_canvas.configure(
            scrollregion=sidebar_canvas.bbox("all")))
        sidebar_canvas.bind("<Configure>", lambda e: sidebar_canvas.itemconfigure(
            window_id, width=e.width))
        ttk.Label(side, text="Recorded drive region", font=("Segoe UI", 11, "bold")).pack(anchor="w")
        self.case_combo = ttk.Combobox(side, textvariable=self.selected_case,
                                        state="readonly", width=31)
        self.case_combo.pack(fill="x", pady=(3, 6))
        self.case_combo.bind("<<ComboboxSelected>>", lambda _: self._change_case())
        ttk.Label(side, textvariable=self.data_text, foreground="#596474",
                  wraplength=330).pack(anchor="w", pady=(0, 10))

        opts = ttk.Frame(side)
        opts.pack(fill="x", pady=(0, 12))
        ttk.Button(opts, text="Choose DTM TIFF", command=self.choose_dtm).pack(side="left")
        ttk.Button(opts, text="Center map", command=self.center_map).pack(side="left", padx=(8, 0))

        ttk.Label(side, text="Start point", font=("Segoe UI", 10, "bold")).pack(anchor="w")
        self.start_combo = ttk.Combobox(side, textvariable=self.start_name,
                                        state="readonly", width=32)
        self.start_combo.pack(fill="x", pady=(3, 9))
        self.start_combo.bind("<<ComboboxSelected>>", self._selection_changed)
        ttk.Label(side, text="End point", font=("Segoe UI", 10, "bold")).pack(anchor="w")
        self.end_combo = ttk.Combobox(side, textvariable=self.end_name,
                                      state="readonly", width=32)
        self.end_combo.pack(fill="x", pady=(3, 8))
        self.end_combo.bind("<<ComboboxSelected>>", self._selection_changed)
        ttk.Label(side, textvariable=self.distance_text, wraplength=325).pack(anchor="w", pady=(0, 7))
        ttk.Label(side, text="Allowed straight-line distance: 50–500 m (inclusive).",
                  wraplength=310, foreground="#596474").pack(anchor="w", pady=(0, 9))
        self.calculate_button = ttk.Button(side, text="Calculate and compare routes",
                                            command=self.calculate_paths)
        self.calculate_button.pack(fill="x", pady=(0, 7))
        ttk.Button(side, text="Clear selection", command=self.clear_selection).pack(fill="x", pady=(0, 10))

        ttk.Separator(side).pack(fill="x", pady=(0, 9))
        ttk.Label(side, text="Routes and estimated performance",
                  font=("Segoe UI", 11, "bold")).pack(anchor="w", pady=(0, 6))
        for name in ROUTE_NAMES:
            color, _ = ROUTE_STYLES[name]
            row = ttk.Frame(side)
            row.pack(fill="x", pady=(2, 1))
            ttk.Checkbutton(row, text=name, variable=self.show_route[name],
                            command=self._redraw).pack(side="left")
            tk.Label(row, bg=color, width=2).pack(side="right", padx=4)
            ttk.Label(side, textvariable=self.metric_text[name],
                      wraplength=320, justify="left", foreground="#334155").pack(anchor="w", pady=(0, 7))
        ttk.Separator(side).pack(fill="x", pady=(5, 9))
        ttk.Label(side,
                  text="Orange = recorded NASA line. Blue/purple = simulated A* routes.\n"
                       "All displayed times/energy are model estimates, NOT NASA telemetry.\n"
                       "Slope and power settings are experimental; no recharge modeled.",
                  justify="left", wraplength=326, foreground="#7c514b").pack(anchor="w")
        ttk.Label(self, textvariable=self.status_text, relief="groove", padding=8,
                  wraplength=1130).grid(row=3, column=0, columnspan=2,
                                        sticky="ew", pady=(10, 0))

    def _change_case(self) -> None:
        case = self.case_map.get(self.selected_case.get())
        if case is None:
            return
        self._generation += 1
        self.case = case
        self.terrain = None
        self.loading = False
        self.calculating = False
        self.routes.clear()
        self._cache_image_key = None
        self._loaded_map_image = None
        self.dtm_error = ""
        self._refresh_track(projected=False)
        self.start_name.set("")
        self.end_name.set("")
        self._reset_metrics()
        self.data_text.set(
            f"NASA sols {case.get('start', {}).get('sol', '?')}–"
            f"{case.get('end', {}).get('sol', '?')}  |  "
            f"{len(self.points)} markers along recorded trace (~50 m intervals)."
        )
        self.distance_text.set("Select two rover positions")
        self.status_text.set("Real NASA track loaded. Select two markers; loading local DTM if available.")
        self._redraw()
        local_dtm = self.selected_dtm or find_local_dtm(str(case.get("id", "")))
        if local_dtm is not None and local_dtm.is_file():
            self._start_terrain_load(local_dtm)
        else:
            self.status_text.set("NASA track ready. Terrain DTM not found locally. Click 'Choose DTM TIFF' "
                                 "to enable real route optimization (or generate data/dtm_crops).")
        self._update_button()

    def _refresh_track(self, projected: bool) -> None:
        assert self.case is not None
        route_lonlat = self.case["nasa_route_lonlat"]
        if projected:
            self.track_xy = projected_track(self.terrain, route_lonlat)
        else:
            start = self.case["start"]
            end = self.case["end"]
            ref_lon = (float(start["lon"]) + float(end["lon"])) / 2
            ref_lat = (float(start["lat"]) + float(end["lat"])) / 2
            self.track_xy = local_xy(route_lonlat, ref_lon, ref_lat)
        samples = sample_recorded_track(self.track_xy)
        self.points = samples
        self.by_name = {p.name: p for p in samples}
        names = list(self.by_name)
        self.start_combo.configure(values=names)
        self.end_combo.configure(values=names)
        self.center_xy = map_center(self.track_xy)

    def _start_terrain_load(self, path: Path) -> None:
        from copy import deepcopy
        assert self.case is not None
        generation = self._generation
        case = deepcopy(self.case)
        self.terrain = None
        self.loading = True
        self._update_button()
        self.status_text.set(f"Loading REAL Mars elevation from {path.name}...")

        def work():
            try:
                # terrain.py currently uses `Affine @ (x, y)`. The version of
                # affine bundled with some rasterio installations implements
                # point transforms only with `*`. Supply the equivalent alias
                # when needed so the existing team file works unchanged.
                from affine import Affine
                if getattr(Affine, "__matmul__", None) is None:
                    Affine.__matmul__ = Affine.__mul__
                from terrain import load_case
                # Includes the NASA recorded route; 250 m margin supplies a
                # wider swath for the fixed 500 x 500 m view and route detours.
                terrain = load_case(case, dtm_path=str(path), margin_m=255.0, cell_size=2.0)
                self._result_queue.put((generation, "terrain", terrain, str(path)))
            except Exception as exc:
                self._result_queue.put((generation, "terrain_error", str(exc), str(path)))

        threading.Thread(target=work, daemon=True).start()

    def choose_dtm(self) -> None:
        path = filedialog.askopenfilename(
            parent=self.parent, title="Choose georeferenced Mars DTM GeoTIFF",
            filetypes=[("GeoTIFF images", "*.tif *.tiff"), ("All files", "*.*")],
        )
        if path and self.case is not None:
            self._generation += 1
            self.selected_dtm = Path(path)
            self.routes.clear()
            self._reset_metrics()
            self._start_terrain_load(self.selected_dtm)

    def _poll_worker_results(self) -> None:
        try:
            while True:
                generation, kind, payload, other = self._result_queue.get_nowait()
                if generation != self._generation:
                    continue  # user switched case or selected a different route
                if kind == "terrain":
                    self.terrain = payload
                    self.loading = False
                    previous_start, previous_end = self.start_name.get(), self.end_name.get()
                    self._refresh_track(projected=True)
                    self.start_name.set(previous_start if previous_start in self.by_name else "")
                    self.end_name.set(previous_end if previous_end in self.by_name else "")
                    self._cache_image_key = None
                    self._selection_changed()
                    self.status_text.set("HiRISE elevation loaded. Choose two ~50 m-spaced NASA track markers "
                                         "and click Calculate. Orange = recorded NASA track.")
                elif kind == "terrain_error":
                    self.loading = False
                    self.terrain = None
                    self.dtm_error = str(payload)
                    self.status_text.set(f"Could not load {Path(other).name}: {payload}. "
                                         "NASA track can still be viewed, but optimization needs a DTM.")
                elif kind == "routes":
                    self.calculating = False
                    self.routes = payload
                    self._update_metric_labels()
                    self.status_text.set("Routes finished. Orange is NASA recorded geometry; "
                                         "all time/energy are predictions from the terrain model.")
                elif kind == "routes_error":
                    self.calculating = False
                    self.routes.clear()
                    self._reset_metrics()
                    self.status_text.set(f"Route calculation failed: {payload}")
                self._update_button()
                self._redraw()
        except queue.Empty:
            pass
        try:
            self.after(120, self._poll_worker_results)
        except tk.TclError:
            pass

    def _reset_metrics(self) -> None:
        for name in ROUTE_NAMES:
            self.metric_text[name].set("Not calculated")

    def _update_metric_labels(self) -> None:
        for name in ROUTE_NAMES:
            route = self.routes.get(name)
            if route is None:
                self.metric_text[name].set("Not calculated")
                continue
            if route.distance_m is None:
                self.metric_text[name].set("No route found. " + route.note)
                continue
            time = "N/A" if route.time_s is None else f"{route.time_s / 60:.1f} min"
            energy = "N/A" if route.energy_wh is None else f"{route.energy_wh:.2f} Wh"
            extra = ""
            if route.ascent_m is not None:
                extra = f"  |  +{route.ascent_m:.1f} / -{route.descent_m:.1f} m"
            self.metric_text[name].set(
                f"Distance {route.distance_m:.1f} m  |  Time {time}  |  Energy {energy}"
                f"{extra}\n{route.note}"
            )

    def _selected_points(self) -> tuple[RoverPoint | None, RoverPoint | None]:
        return self.by_name.get(self.start_name.get()), self.by_name.get(self.end_name.get())

    def _valid_selection(self) -> tuple[bool, float]:
        a, b = self._selected_points()
        if a is None or b is None:
            return False, 0.0
        d = math.hypot(a.x_m - b.x_m, a.y_m - b.y_m)
        return a.name != b.name and MIN_DISTANCE_M - 1e-5 <= d <= MAX_DISTANCE_M + 1e-5, d

    def _update_button(self) -> None:
        valid, _ = self._valid_selection()
        self.calculate_button.configure(state="normal" if valid and self.terrain is not None
                                        and not self.loading and not self.calculating else "disabled")

    def _selection_changed(self, _event=None) -> None:
        self._generation += 1 if self.calculating else 0
        self.calculating = False
        self.routes.clear()
        self._reset_metrics()
        valid, d = self._valid_selection()
        a, b = self._selected_points()
        if a is None or b is None:
            self.distance_text.set("Select two rover positions")
        else:
            self.distance_text.set(f"Straight-line distance: {d:.1f} m  |  NASA track separation: "
                                   f"{abs(a.along_m - b.along_m):.1f} m")
        if a is not None and b is not None:
            if valid:
                self.status_text.set("Selection is valid. Calculate two optimized routes when the DTM is loaded.")
            else:
                self.status_text.set("Choose DIFFERENT markers 50–500 m apart in straight-line distance.")
        self._update_button()
        self._redraw()

    def calculate_paths(self) -> None:
        ok, distance = self._valid_selection()
        if not ok:
            messagebox.showwarning("Choose points", "Choose different NASA track points 50–500 m apart.")
            return
        if self.terrain is None:
            messagebox.showwarning("DTM required", "Load a real HiRISE DTM to run path optimization.")
            return
        start, end = self._selected_points()
        assert start is not None and end is not None
        self._generation += 1
        generation = self._generation
        terrain = self.terrain
        track = tuple(self.track_xy)
        self.routes.clear()
        self._reset_metrics()
        self.calculating = True
        self._update_button()
        self.status_text.set(f"Calculating fastest and lowest-energy paths for {distance:.1f} m separation...")

        def work():
            try:
                routes = calculate_real_routes(terrain, track, start, end)
                self._result_queue.put((generation, "routes", routes, None))
            except Exception as exc:
                self._result_queue.put((generation, "routes_error", str(exc), None))

        threading.Thread(target=work, daemon=True).start()

    def clear_selection(self) -> None:
        self.start_name.set("")
        self.end_name.set("")
        self._selection_changed()
        self.status_text.set("Selection cleared. Choose two NASA track markers.")

    def center_map(self) -> None:
        if self.track_xy:
            self.center_xy = map_center(self.track_xy)
            self._cache_image_key = None
            self._redraw()

    def _map_bounds(self) -> tuple[float, float, float, float]:
        cx, cy = self.center_xy
        return (cx - MAP_HALF_SPAN_M, cx + MAP_HALF_SPAN_M,
                cy - MAP_HALF_SPAN_M, cy + MAP_HALF_SPAN_M)

    def _world_to_pixel(self, x: float, y: float) -> XY:
        ox, oy, size = self._map_geometry
        cx, cy = self.center_xy
        return (ox + size / 2 + (x - cx) * size / (MAP_HALF_SPAN_M * 2),
                oy + size / 2 - (y - cy) * size / (MAP_HALF_SPAN_M * 2))

    def _map_click(self, event: tk.Event) -> None:
        winner = None
        best = 13.0
        for name, (x, y) in self._marker_pixels.items():
            d = math.hypot(event.x - x, event.y - y)
            if d < best:
                best, winner = d, name
        if winner is None:
            return
        if not self.start_name.get() or self.end_name.get():
            self.start_name.set(winner)
            self.end_name.set("")
        else:
            self.end_name.set(winner)
        self._selection_changed()

    def _redraw(self) -> None:
        if not hasattr(self, "canvas") or not self.canvas.winfo_exists():
            return
        canvas = self.canvas
        width, height = canvas.winfo_width(), canvas.winfo_height()
        if width < 90 or height < 90:
            return
        canvas.delete("all")
        size = max(1, min(width - 20, height - 20))
        ox, oy = int((width - size) / 2), int((height - size) / 2)
        self._map_geometry = (ox, oy, size)
        canvas.create_rectangle(ox, oy, ox + size, oy + size, fill="#805d47", outline="#e5e7eb")

        if Image is not None and self.terrain is not None:
            bounds = self._map_bounds()
            key = (id(self.terrain), self.center_xy, size)
            if key != self._cache_image_key:
                rgb = terrain_rgb(self.terrain, bounds, size)
                self._loaded_map_image = Image.fromarray(rgb, "RGB")
                self._canvas_image = ImageTk.PhotoImage(self._loaded_map_image, master=canvas)
                self._cache_image_key = key
            canvas.create_image(ox, oy, anchor="nw", image=self._canvas_image)
        else:
            for i in range(1, 10):
                pos = ox + i * size / 10
                y = oy + i * size / 10
                canvas.create_line(pos, oy, pos, oy + size, fill="#b0876b", dash=(2, 8))
                canvas.create_line(ox, y, ox + size, y, fill="#b0876b", dash=(2, 8))
            label = "NO DTM LOADED — NASA track coordinates only" if self.terrain is None else \
                "Install Pillow to display hillshaded real elevation"
            canvas.create_text(ox + 12, oy + 20, anchor="w", fill="white",
                               text=label, font=("Segoe UI", 10, "bold"))

        # 100 m scale grid on the 500 m square and North label.
        for i in range(1, 5):
            pos = ox + i * size / 5
            y = oy + i * size / 5
            canvas.create_line(pos, oy, pos, oy + size, fill="#e8d8c5", dash=(2, 8))
            canvas.create_line(ox, y, ox + size, y, fill="#e8d8c5", dash=(2, 8))
        canvas.create_text(ox + size - 12, oy + 12, text="N ↑", anchor="ne",
                           font=("Segoe UI", 11, "bold"), fill="white")
        canvas.create_text(ox + 12, oy + size - 12, text="100 m per grid interval",
                           anchor="sw", font=("Segoe UI", 9, "bold"), fill="white")

        if self.track_xy and self.show_route[ACTUAL].get():
            track_px = [q for pt in self.track_xy for q in self._world_to_pixel(*pt)]
            if len(track_px) >= 4:
                canvas.create_line(*track_px, fill="#663a23", width=3)
        for name, route in self.routes.items():
            if not self.show_route[name].get() or len(route.coordinates) < 2:
                continue
            pixels = [q for pt in route.coordinates for q in self._world_to_pixel(*pt)]
            color, dash = ROUTE_STYLES[name]
            canvas.create_line(*pixels, fill=color, width=4, dash=dash,
                               capstyle=tk.ROUND, joinstyle=tk.ROUND)

        self._marker_pixels.clear()
        for i, point in enumerate(self.points):
            x, y = self._world_to_pixel(point.x_m, point.y_m)
            if not (ox <= x <= ox + size and oy <= y <= oy + size):
                continue
            self._marker_pixels[point.name] = (x, y)
            start, end = self.start_name.get(), self.end_name.get()
            selected = point.name in (start, end)
            radius = 7 if selected else 5
            color = ("#2dd4bf" if point.name == start else
                     "#ffcf56" if point.name == end else "#1f2937")
            canvas.create_oval(x-radius, y-radius, x+radius, y+radius,
                               fill=color, outline="white", width=2)
            canvas.create_text(x + 9, y - 8, text=point.name, anchor="w",
                               fill="white", font=("Segoe UI", 9, "bold"))
        if self.terrain is not None:
            canvas.create_text(ox + 12, oy + 12, anchor="nw", fill="white",
                               text="HiRISE DTM shaded elevation (not a photo)",
                               font=("Segoe UI", 9, "bold"))
        canvas.create_rectangle(ox, oy, ox + size, oy + size,
                                outline="#f8fafc", width=2)


def launch_ui(*, cases_path: str | Path = CASES_FILE,
              dtm_path: str | Path | None = None) -> None:
    """Entry point compatible with the repo's existing main.py."""
    root = tk.Tk()
    root.title("Perseverance • Route Optimization")
    root.geometry("1270x830")
    root.minsize(990, 680)
    MarsRoverUI(root, cases_path=cases_path, dtm_path=dtm_path)
    root.mainloop()


if __name__ == "__main__":
    launch_ui()
